struct Target {
 const Boundary&b;Surface&s;std::string mode;double amplitude,frequency;std::vector<double>latmean;double last_removed_mean=0;
 Target(const Boundary&b_,Surface&s_,std::string mode_,double amp=3.,double freq=2*PI):b(b_),s(s_),mode(mode_),amplitude(amp),frequency(freq){
  if(mode!="real"||!b.angular)return;latmean.assign((size_t)b.nt*s.n*b.nl,0.);
  for(int j=0;j<s.n;++j){double lo=PI/2-(j+1)*s.dt,hi=PI/2-j*s.dt;std::vector<double>weights(b.na,0.);double x=lo;
   while(x<hi-1e-14){int a;double y;bool clamp=false;
