  if(b.nt==1){t=0;ft=0;}int t1=std::min(t+1,b.nt-1);
  auto value=[&](int j,int l){return (1-ft)*latmean[((size_t)t*s.n+j)*b.nl+l]+ft*latmean[((size_t)t1*s.n+j)*b.nl+l];};
  for(int k=0;k<s.m;++k){double lo=wrap(k*s.dp-b.rotation*(time-b.epoch)-b.offset),hi=lo+s.dp,x=lo;
   while(x<hi-1e-14){double xx=wrap(x+1e-14);auto q=std::upper_bound(b.lons.begin(),b.lons.end(),xx);int l=q==b.lons.begin()?b.nl-1:int(q-b.lons.begin()-1),l1=(l+1)%b.nl;double left=b.lons[l],right=b.lons[l1];if(l1==0)right+=2*PI;if(xx<left)xx+=2*PI;double dx=std::min(hi-x,right-xx);if(dx<1e-13){x+=1e-13;continue;}double f0=(xx-left)/(right-left),f1=(xx+dx-left)/(right-left),f=.5*(f0+f1);
    for(int j=0;j<s.n;++j)out[s.ix(j,k)]+=dx*((1-f)*value(j,l)+f*value(j,l1))/s.dp;x+=dx;
   }
  }
